 insert into public.consulta_lotes(id,user_id,nome,tipo) select lot,uid,'CONCURRENCY TEST','campanha' from digi_fixture; insert into public.consulta_jobs(lote_id,user_id,nome,cpf,telefone) select lot,uid,'TEST','00000000191','11999999999' from digi_fixture; do $$ begin begin insert into public.consulta_jobs(lote_id,user_id,nome,cpf,telefone) select lot,uid,'DUPLICATE','00000000191','11999999999' from digi_fixture; raise exception 'Duplicate unexpectedly accepted'; exception when unique_violation then null; end; end $$; rollback;
